const fs=require('fs'),path=require('path');const root=path.resolve(__dirname,'..');const read=p=>JSON.parse(fs.readFileSync(path.join(root,p),'utf8').replace(/^\uFEFF/,''));const save=(p,v)=>fs.writeFileSync(path.join(root,p),typeof v==='string'?v:JSON.stringify(v,null,2)+'\n','utf8');
const data=[
['M01','NIST TN1297 Reporting Uncertainty','https://www.nist.gov/pml/nist-technical-note-1297/nist-tn-1297-7-reporting-uncertainty','Raportarea componentelor incertitudinii și a factorului de acoperire','full_primary_web_text','Document istoric; pagina indică faptul că nu mai este actualizată. Nu furnizează pragurile produsului.'],
['M02','3MF Specifications','https://3mf.io/spec/','Specificația de bază și extensiile pentru schimbul modelelor de imprimare','primary_specification_index','Index citit; nu pretindem validarea unui export implementat sau lectura integrală a tuturor extensiilor.'],
['M03','ODA Drawings SDK','https://www.opendesign.com/products/drawings','Existența unei căi SDK pentru integrarea DWG','primary_vendor_page','Termenii licenței și platforma concretă trebuie verificați înainte de integrare; fără preț estimat.'],
['M04','BOP Challenge 2019 Evaluation','https://bop.felk.cvut.cz/challenges/bop-challenge-2019/','Evaluare 6D cu VSD MSSD MSPD și tratarea simetriei','primary_benchmark_page','Protocol istoric de benchmark; pragurile EVA sunt propuse separat.'],
['M05','WCAG 2.2','https://www.w3.org/TR/WCAG22/','Reper normativ pentru accesibilitatea conținutului web','primary_standard_sections','Consultare orientată pe criterii; nu audit de conformitate efectuat pe aplicația nativă.'],
['M06','Open3D Multiway Registration','https://www.open3d.org/docs/release/tutorial/pipelines/multiway_registration.html','Înregistrare multiplă cu pose graph și legături incerte','primary_documentation','Exemplu de metodă; nu dovedește acuratețea EVA sau originalitatea algoritmului.'],
['M07','Regulamentul UE 2016/679','https://eur-lex.europa.eu/eli/reg/2016/679/oj/eng','Sursă normativă pentru analiza protecției datelor în UE','official_link_access_limited','Instrumentul a returnat conținut insuficient pentru lectura integrală; nu folosim această accesare ca aviz juridic sau verificare exhaustivă.'],
['M08','Apple Scanning the rooms of a single structure','https://developer.apple.com/documentation/roomplan/scanning-the-rooms-of-a-single-structure','Unirea camerelor într-o structură și relocalizarea sesiunii','primary_indexed_text','Suportul și profilul dimensional se verifică pe hardware; sursa nu garantează toleranțele propuse.']
].map(([id,title,url,claim,verification,limitations])=>({id,title,url,claim,verification,limitations,accessed_at:'2026-10-02',recorded_at:new Date().toISOString()}));
save('06_surse/manager_sources.json',{schema_version:'1.0',sources:data});
const all=['apple_sources.json','robotics_sources.json','manager_sources.json'].flatMap(p=>read('06_surse/'+p).sources.map(s=>({...s,register:p})));
save('06_surse/registru_unificat.json',{at:new Date().toISOString(),sources:all,unique_urls:new Set(all.map(s=>s.url)).size});
let md='# Bibliografie și limitele documentării\n\nRegistrul conține '+all.length+' înregistrări de surse primare, cu '+new Set(all.map(s=>s.url)).size+' URL-uri distincte. Numărul nu dovedește exhaustivitate. Înregistrările disting text consultat, index și acces limitat. Nu sunt reproduse integral articole protejate; fișele de mai jos sunt rezumate originale și puncte de acces.\n\n';
for(const s of all)md+=`## ${s.id} ${s.title}\n\n[Deschide sursa primară](${s.url})\n\n**Afirmație susținută:** ${s.claim}\n\n**Consultare:** ${s.accessed_at}; ${s.verification}.\n\n**Limite:** ${s.limitations}\n\n`;
md+='## Documente precedente și surse locale\n\nCRITERII_MOSTENITE păstrează pragurile dosarului precedent. NIST_TN1297.pdf este o copie a documentului guvernamental păstrat deja în documentația anterioară; proveniența și hashul sunt în local_sources.json. Nu afirmăm redescărcarea sau recitirea integrală a PDF-ului în această sesiune. Pentru feedback de piață, dosarul precedent este reper exploratoriu; această extindere nu inventează interviuri sau comentarii noi.\n';
save('06_surse/BIBLIOGRAFIE.md',md);
console.log(JSON.stringify({records:all.length,urls:new Set(all.map(s=>s.url)).size}));
